INSERT INTO clinic_wording (row_id, new_key, fields, en, sites, note) VALUES
  (65, '65|||מרפאה לבריאות הנפש: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"מכון למרחב","svc":"מרפאה לבריאות הנפש: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"ילדים, נוער ומבוגרים","region":"ירושלים, בית שמש, ביתר עילית, רחובות","founded":"2016","meeting":"in_person","cost":"קופות החולים","specialty":"","approaches":"","languages":"","notes":"מותאם לציבור הדתי והחרדי. גם טיפול זוגי, משפחתי וקבוצתי, ואבחון פסיכולוגי.","phone":"02-5954571","phoneLabel":"טלפון","phoneShowNumber":false,"email":"office@lamerchav.org.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Machon Lamerchav","svc":"Mental health clinic: assessment and medication, and also psychotherapy. At the clinic.","target":"Children, youth, and adults","region":"Jerusalem, Beit Shemesh, Beitar Illit, Rehovot","founded":"2016","cost":"Health funds","notes":"Adapted for the religious and Haredi community. Also couples, family, and group therapy, and psychological assessment.","phoneLabel":"Phone","emailLabel":"Email"}'::jsonb, NULL, '20.11.2026: נבדק מול https://www.lamerchav.org.il/ . הניסוח אושר עם אצוות המרפאות.'),
  (90, '90|||מרכז לאבחון ולטיפול: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"ME Mental Experts","svc":"מרכז לאבחון ולטיפול: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"ילדים, נוער ומבוגרים","region":"פתח תקווה, כפר סבא, חיפה, אילת","founded":"","meeting":"in_person","cost":"","specialty":"","approaches":"","languages":"","notes":"גם אבחון נוירולוגי, וטיפול משפחתי וקבוצתי.","phone":"*5806","phoneLabel":"מוקד","phoneShowNumber":false,"email":"info@mexp.co.il","emailLabel":"אימייל","emailShowAddress":false,"whatsapp":"","whatsappLabel":""}'::jsonb, '{"org":"ME Mental Experts","svc":"A center for assessment and treatment: assessment and medication, and also psychotherapy. At the clinic.","target":"Children, youth, and adults","region":"Petah Tikva, Kfar Saba, Haifa, Eilat","notes":"Also neurological assessment, and family and group therapy.","phoneLabel":"Information line","emailLabel":"Email","siteLabels":["Petah Tikva","Kfar Saba","Haifa","Eilat"],"siteAddresses":["7 Mota Gur St, Petah Tikva","3 Rappaport St, Kfar Saba","55 HaHistadrut St, Haifa","6 Derech HaArava, Eilat"]}'::jsonb, '[{"label":"פתח תקווה","address":"מוטה גור 7, פתח תקווה","lat":32.0937768,"lng":34.8648004,"phone":"","email":"","note":"","sort_order":0},{"label":"כפר סבא","address":"רפפורט 3, כפר סבא","lat":32.1918767,"lng":34.891643,"phone":"","email":"","note":"","sort_order":1},{"label":"חיפה","address":"ההסתדרות 55, חיפה","lat":32.7935104,"lng":35.0373412,"phone":"","email":"","note":"","sort_order":2},{"label":"אילת","address":"דרך הערבה 6, אילת","lat":29.7361039,"lng":35.0060437,"phone":"","email":"","note":"","sort_order":3}]'::jsonb, '20.11.2026: נבדק מול https://mexp.co.il/ . הוואטסאפ שהיה בכרטיס לא מופיע בדף הבית, והוסר. מי משלם לא נכתב באתר. כפר סבא וחיפה אותרו עד הבניין. פתח תקווה ואילת אותרו עד הרחוב. הניסוח אושר עם אצוות המרפאות.'),
  (279, '279|||טיפול יום פסיכיאטרי: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"בית רעים","svc":"טיפול יום פסיכיאטרי: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"מבוגרים","region":"נתניה (אזור התעשייה פולג)","founded":"2007","meeting":"in_person","cost":"קופת החולים (טופס 17) או משרד הביטחון, וגם פרטי","specialty":"חרדה, דיכאון, דו־קוטבית, מצבים פסיכוטיים, פוסט־טראומה, הפרעות הסתגלות, הפרעות אישיות","approaches":"פסיכותרפיה, DBT, פסיכודרמה, טיפול באומנות, ריפוי בעיסוק","languages":"","notes":"של האגודה לבריאות הציבור. הפניה מפסיכיאטר. מקבל פניות מכל הארץ.","phone":"09-8851290","phoneLabel":"מזכירות","phoneShowNumber":false,"email":"netanya@tipulyom.co.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Beit Re''im","svc":"Psychiatric day treatment: assessment and medication, and also psychotherapy. At the clinic.","target":"Adults","region":"Netanya (Poleg industrial area)","founded":"2007","cost":"A health fund (form 17) or the Ministry of Defense, and also private","specialty":"Anxiety, depression, bipolar disorder, psychotic states, post-trauma, adjustment disorders, personality disorders","approaches":"Psychotherapy, DBT, psychodrama, art therapy, occupational therapy","notes":"Run by the Association for Public Health. Referral from a psychiatrist. Accepts referrals from anywhere in the country.","phoneLabel":"Secretary","emailLabel":"Email"}'::jsonb, NULL, '20.11.2026: נבדק מול https://www.aguda.co.il/services/%D7%91%D7%99%D7%AA-%D7%A8%D7%A2%D7%99%D7%9D-%D7%A0%D7%AA%D7%A0%D7%99%D7%94/ . שעות היום הוסרו מהכרטיס. הניסוח אושר עם אצוות המרפאות.'),
  (280, '280|||מרפאה לבריאות הנפש: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"מרפאת הנגב","svc":"מרפאה לבריאות הנפש: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"מבוגרים","region":"אופקים","founded":"2006","meeting":"in_person","cost":"קופות החולים","specialty":"","approaches":"פסיכותרפיה ממוקדת","languages":"","notes":"של האגודה לבריאות הציבור. הפניה מרופא משפחה. גם הגשה לוועדות סל שיקום. כתובת: הרצל 37, אופקים.","phone":"08-9982640","phoneLabel":"מזכירות","phoneShowNumber":false}'::jsonb, '{"org":"Negev Clinic","svc":"Mental health clinic: assessment and medication, and also psychotherapy. At the clinic.","target":"Adults","region":"Ofakim","founded":"2006","cost":"Health funds","approaches":"Focused psychotherapy","notes":"Run by the Association for Public Health. Referral from a family doctor. Also applications to rehabilitation-basket committees. Address: 37 Herzl St, Ofakim.","phoneLabel":"Secretary","siteLabels":["Ofakim"],"siteAddresses":["37 Herzl St, Ofakim"]}'::jsonb, NULL, '20.11.2026: נבדק מול https://www.aguda.co.il/services/%D7%9E%D7%A8%D7%A4%D7%90%D7%AA-%D7%90%D7%95%D7%A4%D7%A7%D7%99%D7%9D/ . הניסוח אושר עם אצוות המרפאות.'),
  (291, '291|||תוכנית קהילתית אחרי אפיזודה פסיכוטית ראשונה: טיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"נויגייט","svc":"תוכנית קהילתית אחרי אפיזודה פסיכוטית ראשונה: טיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"צעירים","region":"הוד השרון, באר יעקב, ירושלים, פתח תקווה, חיפה, בת ים, השרון, עכו","founded":"","meeting":"in_person","cost":"","specialty":"אפיזודה פסיכוטית ראשונה","approaches":"","languages":"","notes":"גם ליווי משפחתי, תעסוקה והשכלה. פרטי כל מרפאה באתר. מרפאת בת ים פועלת בהדספייס.","phone":"","phoneLabel":"","phoneShowNumber":false}'::jsonb, '{"org":"NAVIGATE","svc":"A community program after a first psychotic episode: medication, and also psychotherapy. At the clinic.","target":"Young adults","region":"Hod Hasharon, Beer Yaakov, Jerusalem, Petah Tikva, Haifa, Bat Yam, the Sharon, Acre","specialty":"First psychotic episode","notes":"Also family support, employment, and education. Details of each clinic are on the website. The Bat Yam clinic runs at Headspace."}'::jsonb, NULL, '20.11.2026: נבדק מול https://www.navigateisrael.com/ . אין מספר ציבורי אחד, ומי משלם לא נכתב. מספרי הצוות לא על הכרטיס. הניסוח אושר עם אצוות המרפאות.'),
  (338, '338|||מרפאת חוץ: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"מרפאת עירון","svc":"מרפאת חוץ: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"מבוגרים","region":"שער מנשה","founded":"","meeting":"in_person","cost":"","specialty":"","approaches":"","languages":"","notes":"ליד שער המרכז הרפואי לבריאות הנפש שער מנשה. גם טיפול יום מרפאתי. הפניה מרופא משפחה, וגם פנייה עצמית. מחלקת האשפוז-יום, המרפאה לטראומה מינית ומרכז הייעוץ למשפחות נשארים בכרטיסים נפרדים.","phone":"04-6278111","phoneLabel":"מזכירות","phoneShowNumber":false}'::jsonb, '{"org":"Iron Clinic","svc":"Outpatient clinic: assessment and medication, and also psychotherapy. At the clinic.","target":"Adults","region":"Sha''ar Menashe","notes":"Next to the gate of the Sha''ar Menashe Mental Health Center. Also clinic day treatment. Referral from a family doctor, and also self-referral. The separate day hospital, the sexual-trauma clinic, and the family counseling center stay on their own cards.","phoneLabel":"Secretary"}'::jsonb, NULL, '20.11.2026: נבדק מול https://www.shaar-menashe.org/?ArticleID=157&CategoryID=178 . שעות הקבלה הוסרו. מי משלם לא נכתב בדף. הניסוח אושר עם אצוות המרפאות.'),
  (345, '345|||מרכז פרטי לטיפול ואבחון: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"מרכז גוני","svc":"מרכז פרטי לטיפול ואבחון: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"ילדים, נוער ומבוגרים","region":"צהלה, תל אביב","founded":"","meeting":"in_person","cost":"","specialty":"חרדה, OCD, דיכאון, טראומה, קשיי ויסות, אוטיזם, קשב, הפרעות אכילה, התמכרויות","approaches":"טיפול דינמי, DBT, CBT, EMDR, PE, טיפול באומנות","languages":"","notes":"גם טיפול זוגי, משפחתי ודיאדי, והדרכת הורים.","phone":"058-7993988","phoneLabel":"טלפון","phoneShowNumber":false,"email":"gonicenter@gmail.com","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Goni Center","svc":"Private center for treatment and assessment: assessment and medication, and also psychotherapy. At the clinic.","target":"Children, youth, and adults","region":"Tzahala, Tel Aviv","specialty":"Anxiety, OCD, depression, trauma, emotion regulation, autism, ADHD, eating disorders, addictions","approaches":"Dynamic therapy, DBT, CBT, EMDR, PE, art therapy","notes":"Also couples, family, and dyadic therapy, and parent guidance.","phoneLabel":"Phone","emailLabel":"Email","siteLabels":["Tzahala, Tel Aviv"],"siteAddresses":["11 Anatot St, Tzahala, Tel Aviv"]}'::jsonb, NULL, '20.11.2026: נבדק מול https://gonicenter.co.il/ . שיחת ייעוץ ללא עלות לא נכתבה בדף, ולכן לא על הכרטיס. מי משלם לא נכתב. וואטסאפ מוצע בלי מספר. הניסוח אושר עם אצוות המרפאות.'),
  (346, '346|||מרכז פרטי לתמיכה רגשית ונפשית: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"מרכז ד״ר טל","svc":"מרכז פרטי לתמיכה רגשית ונפשית: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"ילדים, נוער ומבוגרים","region":"תל אביב, ירושלים, חיפה","founded":"2001","meeting":"in_person","cost":"פרטי","specialty":"חרדה, דיכאון, פוסט־טראומה, קשב, אוטיזם, התמכרויות, סכיזופרניה, פסיכוזה, הפרעות אכילה","approaches":"טיפול דינמי, CBT, DBT, EMDR","languages":"","notes":"גם טיפול זוגי ומשפחתי. בסניף ירושלים יש מענה גם ברוסית.","phone":"03-6413483","phoneLabel":"טלפון","phoneShowNumber":false,"email":"mail@drtal.co.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Dr. Tal Center","svc":"Private center for emotional and mental support: assessment and medication, and also psychotherapy. At the clinic.","target":"Children, youth, and adults","region":"Tel Aviv, Jerusalem, Haifa","founded":"2001","cost":"Private","specialty":"Anxiety, depression, post-trauma, ADHD, autism, addictions, schizophrenia, psychosis, eating disorders","approaches":"Dynamic therapy, CBT, DBT, EMDR","notes":"Also couples and family therapy. The Jerusalem branch also offers care in Russian.","phoneLabel":"Phone","emailLabel":"Email","siteLabels":["Jerusalem","Haifa"],"siteAddresses":["43a Emek Refaim St, Jerusalem","68 Moriah Blvd, Haifa"]}'::jsonb, '[{"label":"ירושלים","address":"עמק רפאים 43א, ירושלים","lat":31.7619324,"lng":35.2179409,"phone":"","email":"","note":"","sort_order":0},{"label":"חיפה","address":"שדרות מוריה 68, חיפה","lat":32.7950503,"lng":34.9847309,"phone":"","email":"","note":"","sort_order":1}]'::jsonb, '20.11.2026: נבדק מול https://www.drtal.co.il/ . אונליין ורמת אביב לא בדף. אין רחוב לתל אביב בדף. חיפה אותרה עד הבניין. ירושלים אותרה כעמק רפאים 43. הניסוח אושר עם אצוות המרפאות.'),
  (347, '347|||מכון פרטי לאבחון ולייעוץ: אבחון פסיכיאטרי, וגם פסיכותרפיה. במרפאה.', '{"org":"הכח לשנות","svc":"מכון פרטי לאבחון ולייעוץ: אבחון פסיכיאטרי, וגם פסיכותרפיה. במרפאה.","target":"ילדים, נוער ומבוגרים","region":"ראשון לציון","founded":"","meeting":"in_person","cost":"","specialty":"חרדה, דיכאון, קשב, טראומה, אוטיזם","approaches":"טיפול דינמי","languages":"","notes":"גם טיפול משפחתי וקבוצתי, ריפוי בעיסוק וקלינאות תקשורת.","phone":"072-3341926","phoneLabel":"משרד","phoneShowNumber":false,"email":"info@leshanot.co.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"HaKoach Leshanot","svc":"Private institute for assessment and counseling: psychiatric assessment, and also psychotherapy. At the clinic.","target":"Children, youth, and adults","region":"Rishon LeZion","specialty":"Anxiety, depression, ADHD, trauma, autism","approaches":"Dynamic therapy","notes":"Also family and group therapy, occupational therapy, and speech therapy.","phoneLabel":"Office","emailLabel":"Email","siteLabels":["Rishon LeZion"],"siteAddresses":["27 Yosef Lishansky St, Rishon LeZion"]}'::jsonb, NULL, '20.11.2026: נבדק מול https://leshanot.co.il/ . גיל מינימום, מי משלם, וטיפול תרופתי לא נכתבו בדף. הניסוח אושר עם אצוות המרפאות.'),
  (348, '348|||מרכז רפואי פרטי: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"קשת רפואה","svc":"מרכז רפואי פרטי: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"ילדים, נוער ומבוגרים","region":"מבשרת ציון","founded":"","meeting":"in_person","cost":"פרטי. החזר מחברות ביטוח לפי תנאי הפוליסה.","specialty":"הפרעות אכילה, דיכאון, חרדה, OCD, פוסט־טראומה, קשב","approaches":"CBT, DBT, EMDR","languages":"","notes":"גם רפואה גופנית באותו מרכז. מרכז נווה להפרעות אכילה.","phone":"073-3214111","phoneLabel":"משרד","phoneShowNumber":false,"email":"Office@keshet-refua.co.il","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Keshet Refua","svc":"Private medical center: assessment and medication, and also psychotherapy. At the clinic.","target":"Children, youth, and adults","region":"Mevaseret Zion","cost":"Private. Reimbursement from insurance companies according to the policy.","specialty":"Eating disorders, depression, anxiety, OCD, post-trauma, ADHD","approaches":"CBT, DBT, EMDR","notes":"Also physical medicine in the same center. Neve center for eating disorders.","phoneLabel":"Office","emailLabel":"Email","siteLabels":["Mevaseret Zion"],"siteAddresses":["1 Tzur St, Mevaseret Zion"]}'::jsonb, NULL, '20.11.2026: נבדק מול https://keshet-refua.co.il/ . הניסוח אושר עם אצוות המרפאות.'),
  (349, '349|||מכון להפרעות אכילה: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"המכון להפרעות אכילה ע״ש אפרת צוק","svc":"מכון להפרעות אכילה: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"מבוגרים","region":"תל אביב","founded":"","meeting":"in_person","cost":"טיפול אמבולטורי דרך קופות החולים","specialty":"אנורקסיה, בולימיה, אכילה כפייתית, השמנה לפני ניתוח בריאטרי או אחריו","approaches":"טיפול דינמי, CBT, DBT, EMDR, טיפול באומנות, פסיכודרמה","languages":"","notes":"בבית החולים השיקומי רעות. גם טיפול אמבולטורי אחרי טיפול היום.","phone":"03-5081000","phoneLabel":"טלפון","phoneShowNumber":false}'::jsonb, '{"org":"The Institute for Treatment of Eating Disorders in Memory of Efrat Zuck","svc":"An eating-disorder institute: assessment and medication, and also psychotherapy. At the clinic.","target":"Adults","region":"Tel Aviv","cost":"Outpatient care through the health funds","specialty":"Anorexia, bulimia, compulsive eating, obesity before or after bariatric surgery","approaches":"Dynamic therapy, CBT, DBT, EMDR, art therapy, psychodrama","notes":"At Reuth Rehabilitation Hospital. Also outpatient care after day treatment.","phoneLabel":"Phone"}'::jsonb, NULL, '20.11.2026: נבדק מול https://www.reuth-mc.org.il/clinics/the-institute-for-treatment-of-eating-disorders/ . הרחוב ומי משלם על טיפול היום לא בדף הזה, והוסרו. הניסוח אושר עם אצוות המרפאות.'),
