  (783, '783|||יחידה לפסיכיאטריה של הפריון: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.', '{"org":"מרכז חוה","svc":"יחידה לפסיכיאטריה של הפריון: אבחון וטיפול תרופתי, וגם פסיכותרפיה. במרפאה.","target":"נשים בהריון, ועד שנה אחרי לידה","region":"תל השומר","meeting":"in_person","cost":"טופס 17, או פרטי לפי מחירון משרד הבריאות","specialty":"פסיכיאטריה של הפריון","approaches":"","notes":"פנייה בטופס באתר, ואחר כך שאלון ב-SMS. מילוי השאלון אינו מבטיח קבלה. פנייה עד ארבעה חודשים מהלידה. אחרי אובדן הריון משבוע 20: פנייה עד ארבעה חודשים, וטיפול עד שנה. גם ייעוץ חד-פעמי לפני הריון, וליווי פסיכיאטרי לנשים עם אנדומטריוזיס במרפאת האנדומטריוזיס בשיבא. אובדן הריון לפני שבוע 20 מופנה למרכז בדרכך. המרפאה בבניין הפסיכיאטריה.","phone":"03-5303352","phoneLabel":"מזכירות","phoneShowNumber":false}'::jsonb, '{"org":"Chava Center","svc":"A perinatal psychiatry unit: assessment and medication, and also psychotherapy. At the clinic.","target":"Women during pregnancy, and up to a year after birth","region":"Tel Hashomer","cost":"Form 17, or private payment according to the Ministry of Health price list","specialty":"Perinatal psychiatry","notes":"Apply with the form on the website, then a questionnaire by SMS. Filling in the questionnaire does not guarantee admission. Apply within four months of the birth. After a pregnancy loss from week 20: apply within four months, and treatment for up to a year. Also a one-time consultation before pregnancy, and psychiatric follow-up for women with endometriosis treated in the endometriosis clinic at Sheba. A pregnancy loss before week 20 is referred to the Bedarkech center. The clinic is in the psychiatry building.","phoneLabel":"Secretary"}'::jsonb, NULL, '20.11.2026: דף שיבא https://www.sheba.co.il/pregnancy/clinics/chava-center-mental-health-for-women החזיר דף ריק. הניסוח עוצב מחדש מהכרטיס הקיים, ושעות הפעילות הוסרו. הניסוח אושר עם אצוות המרפאות.');

-- glossary_card_links.card_key and the organization-member keys follow
-- directory_card_edits.card_key through ON UPDATE CASCADE.
-- site_audit_entries.card_keys is a plain array, so it is rewritten first.

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE(
      (SELECT w.new_key FROM directory_card_edits c JOIN clinic_wording w ON w.row_id = c.row_id WHERE c.card_key = k),
      k
    )
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN directory_card_edits c ON c.card_key = k
  JOIN clinic_wording w ON w.row_id = c.row_id
  WHERE c.card_key IS DISTINCT FROM w.new_key
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    sites = COALESCE(w.sites, c.sites),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM clinic_wording w
WHERE c.row_id = w.row_id;

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN clinic_wording w ON w.row_id = c.row_id
WHERE e.entry_id = c.entry_id;

INSERT INTO directory_entry_locations (row_id, entry_id, label, address, lat, lng, sort_order)
SELECT c.row_id, c.entry_id, s.label, s.address, s.lat, s.lng, s.sort_order
FROM directory_card_edits c
JOIN clinic_wording w ON w.row_id = c.row_id
CROSS JOIN LATERAL jsonb_to_recordset(w.sites) AS s(
  label text,
  address text,
  lat double precision,
  lng double precision,
  sort_order integer
)
WHERE w.sites IS NOT NULL
  AND c.entry_id IS NOT NULL
  AND s.lat IS NOT NULL
  AND s.lng IS NOT NULL
ON CONFLICT (row_id, label) DO UPDATE SET
  entry_id = EXCLUDED.entry_id,
  address = EXCLUDED.address,
  lat = EXCLUDED.lat,
  lng = EXCLUDED.lng,
  sort_order = EXCLUDED.sort_order;

